        return True

    n = len(arr)
    # Check if arr is already sorted (non-decreasing)
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts (0 to n-1)
    for shift in range(1, n):
        # Right shift by 'shift': last 'shift' elements come to front
