import re

def anti_shuffle(s):
    # Split the string into words and spaces (keeping spaces)
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            # preserve spaces as is
            result.append(part)
        else:
            # Sort letters of the word alphabetically
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)

